TOPICS = [
    ('phishing', 'Spot a phishing message', 'Kenal pasti mesej pancingan data', 'A familiar logo is not proof.', 'Logo yang dikenali bukan bukti.', 'Open an official site yourself. Inspect the entire domain and never disclose OTPs or passwords. HTTPS encrypts transport but does not prove that a website is trustworthy.', 'Buka laman rasmi sendiri. Periksa keseluruhan domain dan jangan dedahkan OTP atau kata laluan. HTTPS tidak membuktikan laman boleh dipercayai.', 'A fictional bank SMS says: “Your account is blocked. Send your OTP immediately.” What should you do?', 'SMS bank rekaan meminta OTP anda dengan segera. Apakah tindakan anda?', ['Send the OTP', 'Contact the bank through its official number', 'Reply with your password'], ['Hantar OTP', 'Hubungi bank melalui nombor rasmi', 'Balas dengan kata laluan'], 1, 'Banks do not need you to send OTPs to a message sender. Verify independently.'),
    ('job', 'When a job offer asks you to pay', 'Apabila tawaran kerja meminta bayaran', 'Check the employer before the opportunity.', 'Semak majikan dahulu.', 'Verify the employer through an independent official contact. Upfront fees and promises of large earnings for simple tasks are warning signs. Do not send identity documents to an unverified recruiter.', 'Sahkan majikan melalui hubungan rasmi bebas. Yuran pendahuluan dan janji pendapatan besar bagi tugasan mudah ialah tanda amaran.', 'A fictional recruiter promises RM500 a day and asks for RM50 registration. What is the strongest warning sign?', 'Perekrut rekaan menjanjikan RM500 sehari dan yuran RM50. Apakah tanda amaran utama?', ['The message is short', 'The recruiter uses a phone', 'Payment is required before starting work'], ['Mesej pendek', 'Perekrut menggunakan telefon', 'Bayaran sebelum mula bekerja'], 2, 'Paying to unlock work is a common advance-fee pattern. Verify the employer first.'),
    ('investment', 'Too good to be a safe investment', 'Pelaburan yang terlalu menarik', 'Guaranteed returns deserve scrutiny.', 'Pulangan dijamin perlu diperiksa.', 'All investments carry risk. Check authorization with the relevant regulator and read official alert lists. A professional site, testimonial or absence from an alert list does not establish legitimacy.', 'Semua pelaburan membawa risiko. Semak kebenaran dengan pengawal selia dan baca senarai amaran rasmi.', 'A fictional investment claims a guaranteed 30% weekly return. What is the safest next step?', 'Pelaburan rekaan menjamin pulangan 30% seminggu. Apakah langkah terbaik?', ['Invest quickly', 'Verify authorization with the regulator', 'Trust screenshots of profits'], ['Melabur segera', 'Sahkan kebenaran dengan pengawal selia', 'Percayai tangkap layar keuntungan'], 1, 'Guaranteed unusually high returns are a warning sign. Screenshots and testimonials are not verification.'),
    ('shopping', 'Shop with a little more certainty', 'Membeli dengan lebih yakin', 'Keep payment and buyer protection together.', 'Pastikan perlindungan pembeli.', 'Use established platform payment methods. Check seller history and independent reviews. Be cautious when a seller moves the conversation off-platform or demands direct transfers under pressure.', 'Gunakan kaedah pembayaran platform yang dipercayai. Semak sejarah penjual dan ulasan bebas. Berhati-hati dengan pindahan terus.', 'A fictional seller asks you to leave the marketplace and transfer money directly for a discount. What should you do?', 'Penjual rekaan meminta pindahan terus di luar platform. Apakah tindakan anda?', ['Use the platform’s protected payment flow', 'Transfer immediately', 'Share your banking PIN'], ['Gunakan pembayaran dilindungi platform', 'Pindah segera', 'Kongsi PIN bank'], 0, 'Moving payment outside a platform can remove buyer protections. A discount does not establish trust.'),
    ('impersonation', 'Verify the person behind the title', 'Sahkan individu di sebalik gelaran', 'Authority claims can be copied.', 'Dakwaan kuasa boleh ditiru.', 'Caller ID, agency names and logos can be spoofed. If a caller threatens arrest or demands a transfer to a “safe account”, stop and contact the organization through an independently sourced number.', 'ID pemanggil, nama agensi dan logo boleh dipalsukan. Jika diugut atau diminta pindahan ke “akaun selamat”, hubungi organisasi melalui nombor rasmi.', 'A fictional officer orders a transfer to a “safe account”. What should you do?', 'Pegawai rekaan mengarahkan pindahan ke “akaun selamat”. Apakah tindakan anda?', ['Follow the order', 'Verify with the agency independently', 'Share a TAC'], ['Ikut arahan', 'Sahkan dengan agensi secara bebas', 'Kongsi TAC'], 1, 'Do not transfer money under an unverified authority claim. Hang up and contact official channels.'),
    ('ai', 'A convincing message can still be a scam', 'Mesej meyakinkan masih boleh menipu', 'Good grammar is no guarantee.', 'Tatabahasa baik bukan jaminan.', 'AI can produce polished messages and imitate voices. Judge the request and verify through a known channel. For family emergencies, use a previously agreed code or call a known number yourself.', 'AI boleh menghasilkan mesej kemas dan meniru suara. Nilai permintaan dan sahkan melalui saluran dikenali.', 'A fictional voice note sounds like your relative asking for urgent money. What is the safest response?', 'Nota suara rekaan seperti saudara anda meminta wang segera. Apakah tindakan terbaik?', ['Trust the voice alone', 'Call their known number to confirm', 'Send money before checking'], ['Percayai suara sahaja', 'Telefon nombor dikenali untuk sahkan', 'Hantar wang dahulu'], 1, 'Voice and writing style can be imitated. Independent verification is more reliable than appearance.'),
    ('payment', 'Pause before you pay', 'Berhenti sebelum membayar', 'A moment of verification matters.', 'Pengesahan itu penting.', 'Confirm the recipient and amount, use official payment channels and never share PINs or TACs. If you discover an unauthorized transfer, contact your bank immediately and NSRC 997, then follow official police-report guidance.', 'Sahkan penerima dan jumlah, gunakan saluran rasmi dan jangan kongsi PIN atau TAC. Jika pindahan tidak sah berlaku, hubungi bank segera dan NSRC 997.', 'You notice a fictional unauthorized transfer. What should you do first?', 'Anda melihat pindahan rekaan tanpa kebenaran. Apakah tindakan pertama?', ['Wait until tomorrow', 'Contact your bank immediately', 'Pay a recovery agent'], ['Tunggu esok', 'Hubungi bank segera', 'Bayar ejen pemulihan'], 1, 'Rapid contact with your bank matters. No service can guarantee recovery of stolen funds.'),
    ('verification', 'Build a verification habit', 'Bina tabiat pengesahan', 'Use a separate, trusted channel.', 'Gunakan saluran berasingan dipercayai.', 'Search for the official organization yourself, compare the whole domain, and contact a known number. Use Semak Mule and official regulator resources as supplementary checks. No single check proves safety.', 'Cari organisasi rasmi sendiri, banding keseluruhan domain dan hubungi nombor dikenali. Gunakan Semak Mule sebagai semakan tambahan. Tiada semakan tunggal menjamin keselamatan.', 'A fictional message includes a verification phone number. How should you check the sender?', 'Mesej rekaan memberi nombor untuk pengesahan. Bagaimana menyemak pengirim?', ['Use only the number in the message', 'Find the official contact independently', 'Trust the logo'], ['Guna nombor dalam mesej sahaja', 'Cari hubungan rasmi secara bebas', 'Percayai logo'], 1, 'A scammer can supply their own verification number. Find official contact information yourself.'),
]


def seeded_modules() -> list[dict]:
    return [{'id': k, 'title': en, 'title_ms': ms, 'subtitle': sub, 'subtitle_ms': sub_ms, 'lesson': lesson, 'lesson_ms': lesson_ms, 'minutes': 3 + n % 3, 'question': {'id': k + '-q1', 'prompt': q, 'prompt_ms': q_ms, 'options': opts, 'options_ms': opts_ms, 'correct': correct, 'explanation': why}} for n, (k, en, ms, sub, sub_ms, lesson, lesson_ms, q, q_ms, opts, opts_ms, correct, why) in enumerate(TOPICS)]
